let t_sintonia = 'ND';
try {
  const sintoniaResp = $json;
  const dadosSintonia = sintoniaResp?.dados || [];
  if (Array.isArray(dadosSintonia) && dadosSintonia.length > 0) {
    const hoje = new Date();
    const anoMesAtual = hoje.getFullYear() * 100 + (hoje.getMonth() + 1);
    if (Number(dadosSintonia[0].mesValidadeSelo) >= anoMesAtual) {
      t_sintonia = 'A+';
    }
  }
} catch (e) {
  // Qualquer erro aqui (formato inesperado, chamada anterior falhou) -> ND, nunca trava o D1.
  t_sintonia = 'ND';
}

return [{ json: { t_sintonia } }];

const cndResp = $('Infosimples · CND Federal').first().json;
const cnd = cndResp?.data?.[0] ?? null;
const est = $('Direct Data · CND Estadual').first().json.retorno ?? null;
const t_sintonia = $('Classificar Sintonia').first().json.t_sintonia ?? 'ND';

const entrada = $('When Executed by Another Workflow').first().json;
const econodataQtdeDivida = entrada.divida_uniao_qtde;

// Diagnostico da chamada federal (vai pro retorno e ajuda a auditar falhas).
const cnd_erro = (!cnd && Array.isArray(cndResp?.errors) && cndResp.errors.length)
  ? String(cndResp.errors[0])
  : null;
const cnd_code = cndResp?.code ?? null;

let t_cnd = "ND";
let t_pgfn = "ND";

if (cnd) {
  // ---- Fonte primaria: Infosimples (nova ou 2a via — mesmo efeito pratico) ----
  const tipo = cnd.tipo || "";
  if (tipo.includes("efeitos de negativa")) t_cnd = "Positiva c/ efeitos de negativa";
  else if (tipo === "Positiva") t_cnd = "Positiva";
  else if (tipo === "Negativa") t_cnd = "Negativa";

  t_pgfn = "Não";
  if (cnd.debitos_pgfn === true) {
    t_pgfn = tipo.includes("efeitos de negativa") ? "Parcelada/garantida" : "Irregular";
  }
} else {
  // Fallback: Infosimples nao emitiu a certidao (CNPJ inapto, portal fora, etc).
  // t_cnd continua "ND" — nenhuma fonte alternativa emite a certidao em si.
  // t_pgfn e recuperado via Econodata (dividasResumo.dividas_uniao, ja consultada
  // na Fase 0 do orquestrador — sem custo extra de API aqui).
  //
  // VALIDADO em 2026-08 com PGFN listadevedores.pgfn.gov.br:
  //  - CNPJ com dividasResumo populado e qtde>0 -> confirmado devedor (Americanas).
  //  - CNPJ com dividasResumo=null -> confirmado SEM registro na lista oficial (Colgate).
  // Ou seja, "null" aqui significa "sem divida confirmada", nao "sem dado".
  if (typeof econodataQtdeDivida === 'number') {
    t_pgfn = econodataQtdeDivida > 0 ? "Irregular" : "Não";
  } else {
    t_pgfn = "Não";
  }
}

let t_est = "ND";
if (est) {
  t_est = (!est.possuiDebito || est.efeitoNegativa) ? "Regular" : "Irregular";
}

const gateDisparado = (t_cnd === "Positiva" && t_pgfn === "Irregular")
  ? "G3: CND federal positiva + PGFN irregular"
  : null;

return [{
  json: {
    t_cnd,
    t_pgfn,
    t_est,
    t_sintonia,
    gate_disparado: gateDisparado,
    cnpj_consultado: $('Normalizar CNPJ Matriz').first().json.cnpj_matriz,
    cnd_code,
    cnd_erro,
  }
}];

